// ----- Node modülü olarak dışa aktarım (skill içi kullanım) -----
function tinCountryCheck(code, tin) {
  if (!COUNTRY_TABLE.some((c) => c.code === code)) return null;
  const info = new $n(), msg = new $n();
  const ok = vo(tin, code, info, msg);
  return { ok: ok === true, msg: msg.value || (code + " TIN'i format kuralına uymuyor.") };
}
module.exports = { COUNTRY_TABLE, vo, tinCountryCheck };
